import React, { useState } from 'react';
import { useLocation } from 'react-router-dom';


function MealSuggestionsPage() {
  const location = useLocation();
  const { age, gender, weight, height, activityLevel, calorieNeeds } = location.state || {};
  const [responseData, setResponseData] = useState(null); 
  if (!age || !gender || !weight || !height || !activityLevel || !calorieNeeds) {
    return (
      <div>
        <h2>Meal Suggestions</h2>
        <p>Error: Missing or invalid data</p>
      </div>
    );
  }

  const msg = `Generate meal suggestions tailored to a user's profile: Age: ${age}, Gender: ${gender}, Weight: ${weight}, Height: ${height}, Activity Level: ${activityLevel}, Calorie Needs: ${calorieNeeds} calories/day.`;

  function send(msg) {
    fetch('http://127.0.0.1:5000/process-message', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        message: msg
      })
    })
    .then(response => response.json())
    .then(data => {
      console.log('Response from server:', data);
      setResponseData(data.content); 
    })
    .catch(error => {
      console.error('Error sending message:', error);
    });
  }

const text = responseData;

  function parseMealPlan(text) {
    const lines = text.split('\n');
    const meals = [];
    let currentMeal = null;

    lines.forEach(line => {
        if (line.trim() === '') {
            return; // skip empty lines
        }

        const mealTitleMatch = line.match(/^(.*)\s\((\d+)\s+calories\)$/);
        const totalMatch = line.match(/^Total:\s+(\d+)\s+calories$/);

        if (mealTitleMatch) {
            if (currentMeal) {
                meals.push(currentMeal);
            }
            currentMeal = {
                title: mealTitleMatch[1],
                items: []
            };
        } else if (totalMatch) {
            currentMeal.totalCalories = totalMatch[1];
        } else {
            currentMeal.items.push(line);
        }
    });

    if (currentMeal) {
        meals.push(currentMeal);
    }

    return (
        <div>
            {meals.map((meal, index) => (
                <div key={index}>
                    <h1>{meal.title}</h1>
                    {meal.items.map((item, idx) => (
                        <p key={idx}>{item}</p>
                    ))}
                    <p>Total: {meal.totalCalories} calories</p>
                </div>
            ))}
            <Summary meals={meals} />
        </div>
    );
}

function Summary({ meals }) {
    const grandTotal = meals.reduce((sum, meal) => sum + parseInt(meal.totalCalories), 0);

    return (
        <div>
            <h2>Summary</h2>
            {meals.map((meal, index) => (
                <p key={index}>{meal.title}: {meal.totalCalories} calories</p>
            ))}
            <p>Grand Total: {grandTotal} calories</p>
        </div>
    );
}


  return (
    <div>
      <input type='button' onClick={() => send(msg)} value="Click me" />
      <p>{Summary}</p>
    </div>
  );
}

export default MealSuggestionsPage;
